# 1. Intercept MCP/API calls via an enforcement proxy rather than giving agents direct SaaS tokens
def execute_martech_action(agent_id, untrusted_input_trace, tool_intent):
    # Trace taint from untrusted data (CRM notes, emails) to catch injection before privilege escalation
    taint_level = taint_tracker.evaluate(untrusted_input_trace)

    # Enforce deterministic blast-radius envelopes instead of binary human OAuth scopes
    envelope = blast_radius_engine.get_budget_and_audience_caps(agent_id, max_taint=taint_level)
    if not envelope.permits(tool_intent.projected_cost, tool_intent.affected_records):
        return route_to_asymmetric_review(agent_id, tool_intent, reason="Exceeded envelope")

    # Martech lacks transactional rollback; enforce phased execution (e.g. 1% canary audience) instead of 100% blast
    staged_plan = blast_partitioner.split(tool_intent, steps=[0.01, 0.10, 1.00])

    # Sign cryptographically so the audit log proves agent identity and prompt state, not a borrowed human seat
    lease = identity_broker.mint_ephemeral_sub_identity(agent_id, tool_intent, ttl_sec=30)
    for stage in staged_plan:
        audit_ledger.record_pre_state(lease, stage, prompt_digest=untrusted_input_trace.hash)
        execution_result = martech_proxy.execute(lease, stage)
        # Circuit break on telemetry drift (unusual bounce rates, sudden spend velocity) before next phase
        if anomaly_detector.tripped(execution_result):
            martech_proxy.kill_switch(lease.active_campaign_ids)
            return StageFailure(aborted_at=stage)
    return ExecutionSuccess()

Hush, little agent, begin small and slow;
One low-risk action, one guarded way to go.

Give each its own name, short grants, caps, and trail;
Record data, intent, and each tool call that may fail.

Treat all words it reads as untrusted refrain;
Shadow and simulate before touching a campaign.

Approval queues won’t save what no one can rewind;
We can bound harm and learn, but full safety stays undefined.
